import{_ as t,a,o,a4 as r}from"./chunks/framework.-FZumj2l.js";const m=JSON.parse(`{"title":"Export CMS Pages","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-cms-pages-export","title":"Export CMS Pages (CSV)","description":"Download the CMS pages datagrid as a CSV file — the same data the admin CMS → Pages \\"Export\\" button produces. Honours the same filters as the listing and exports every matching row (not just the current page).","query":"curl -X GET \\"https://your-domain.com/api/admin/cms/pages/export?format=csv\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: text/csv\\" \\\\\\n  --output cms-pages.csv\\n","response":"# Binary response: a text/csv attachment is written to cms-pages.csv\\n# (Content-Type: text/csv; charset=UTF-8\\n#  Content-Disposition: attachment; filename=\\"cms-pages.csv\\"). Sample contents:\\n\\nID,\\"Page Title\\",\\"URL Key\\",Channel,Locale\\n11,\\"Privacy Policy\\",privacy-policy,default,en\\n13,\\"What's new\\",whats-new1,default,en\\n1,\\"About Us\\",about-us,default,en\\n"},{"id":"admin-cms-pages-export-xlsx","title":"Export CMS Pages (XLSX)","description":"Download the CMS pages datagrid as an XLSX file — the same data the admin CMS → Pages \\"Export\\" button produces. Honours the same filters as the listing and exports every matching row (not just the current page).","query":"curl -X GET \\"https://your-domain.com/api/admin/cms/pages/export?format=xlsx\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\\" \\\\\\n  --output cms-pages.xlsx\\n","response":"# Binary response: an XLSX workbook is written to disk\\n# (Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\\n#  Content-Disposition: attachment; filename=\\"cms-pages.xlsx\\").\\n# Same columns as the CSV export, as the first sheet's header row plus one row per record.\\n"},{"id":"admin-cms-pages-export-xls","title":"Export CMS Pages (XLS)","description":"Download the CMS pages datagrid as an XLS file — the same data the admin CMS → Pages \\"Export\\" button produces. Honours the same filters as the listing and exports every matching row (not just the current page).","query":"curl -X GET \\"https://your-domain.com/api/admin/cms/pages/export?format=xls\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: application/vnd.ms-excel\\" \\\\\\n  --output cms-pages.xls\\n","response":"# Binary response: an XLS workbook is written to disk\\n# (Content-Type: application/vnd.ms-excel\\n#  Content-Disposition: attachment; filename=\\"cms-pages.xls\\").\\n# Same columns as the CSV export, as the first sheet's header row plus one row per record.\\n"},{"id":"admin-cms-pages-export-filtered","title":"Export CMS Pages (filtered)","description":"The export honours every listing filter. Here only pages on the default channel in the en locale whose title contains \\"policy\\" are exported.","query":"curl -X GET \\"https://your-domain.com/api/admin/cms/pages/export?format=csv&channel=1&locale=en&page_title=policy\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: text/csv\\" \\\\\\n  --output cms-pages.csv\\n","response":"ID,\\"Page Title\\",\\"URL Key\\",Channel,Locale\\n11,\\"Privacy Policy\\",privacy-policy,default,en\\n"},{"id":"admin-cms-pages-export-bad-format","title":"Unsupported format (422)","description":"Only format=csv is supported. Any other value returns 422.","query":"curl -i -X GET \\"https://your-domain.com/api/admin/cms/pages/export?format=xlsx\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: text/csv\\"\\n","response":"HTTP/1.1 422 Unprocessable Content\\nContent-Type: application/json\\n\\n{\\n  \\"message\\": \\"Only the csv export format is supported.\\"\\n}\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/cms/pages/export.md","filePath":"api/rest-api/admin/cms/pages/export.md","lastUpdated":1784902076000}`),s={name:"api/rest-api/admin/cms/pages/export.md"};function n(d,e,i,c,p,l){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="export-cms-pages" tabindex="-1">Export CMS Pages <a class="header-anchor" href="#export-cms-pages" aria-label="Permalink to &quot;Export CMS Pages&quot;">​</a></h1><p>Downloads the CMS pages datagrid as a <strong>csv, xls or xlsx file</strong> — the same data the admin <strong>CMS → Pages</strong> &quot;Export&quot; button produces. The response is a binary file attachment, not JSON.</p><p>Unlike the <a href="/api/rest-api/admin/cms/pages-list.html">listing</a>, the export is <strong>not paginated</strong> — it streams <strong>every page that matches the current filters</strong>.</p><div class="tip custom-block"><p class="custom-block-title">REST only</p><p>There is no GraphQL counterpart — binary file streams aren&#39;t expressible over GraphQL. Use this REST endpoint for the export.</p></div><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/cms/pages/export</code></td><td>GET</td></tr></tbody></table><h2 id="request-headers" tabindex="-1">Request headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Value</th></tr></thead><tbody><tr><td><code>Authorization</code></td><td><code>Bearer &lt;token&gt;</code></td></tr><tr><td><code>Accept</code></td><td><code>text/csv</code> — <strong>required</strong>. The endpoint only produces <code>text/csv</code>; sending <code>Accept: application/json</code> returns <code>406 Not Acceptable</code>.</td></tr></tbody></table><h2 id="query-parameters" tabindex="-1">Query parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>format</code></td><td>string</td><td>Export format — <code>csv</code> (the default), <code>xls</code> or <code>xlsx</code>. Any other value returns <code>422</code>. Send a matching <code>Accept</code> header: <code>text/csv</code>, <code>application/vnd.ms-excel</code> or <code>application/vnd.openxmlformats-officedocument.spreadsheetml.sheet</code>.</td></tr></tbody></table><p>The export also accepts the <strong>same filters as the <a href="/api/rest-api/admin/cms/pages-list.html">listing</a></strong>:</p><table tabindex="0"><thead><tr><th>Filter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Filter by page ID.</td></tr><tr><td><code>page_title</code></td><td>string</td><td>Partial title match.</td></tr><tr><td><code>url_key</code></td><td>string</td><td>Partial url_key match.</td></tr><tr><td><code>channel</code></td><td>integer</td><td>Channel ID.</td></tr><tr><td><code>locale</code></td><td>string</td><td>Locale code used for translation resolution.</td></tr></tbody></table><h2 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h2><p>The export carries the five datagrid columns, in order:</p><table tabindex="0"><thead><tr><th>Header</th><th>Value</th></tr></thead><tbody><tr><td><code>ID</code></td><td>Page ID.</td></tr><tr><td><code>Page Title</code></td><td>Page title for the resolved locale.</td></tr><tr><td><code>URL Key</code></td><td>The storefront URL slug.</td></tr><tr><td><code>Channel</code></td><td>Channel code.</td></tr><tr><td><code>Locale</code></td><td>Resolved locale code.</td></tr></tbody></table><h2 id="permission" tabindex="-1">Permission <a class="header-anchor" href="#permission" aria-label="Permalink to &quot;Permission&quot;">​</a></h2><p><code>cms</code></p>',17)]))}const u=t(s,[["render",n]]);export{m as __pageData,u as default};
